@Test
public void testAuthenticate_Locked_Exception() {
    userAdmin.setLocked(true);
    userAdmin.setLockedTime(System.currentTimeMillis());
    userAdmin.setWrongTime(3);
    kylinUserService.updateUser(userAdmin);
    UsernamePasswordAuthenticationToken token = new UsernamePasswordAuthenticationToken("ADMIN", "KYLIN", userAdmin.getAuthorities());
    try {
        limitLoginAuthenticationProvider.authenticate(token);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof LockedException);
        String msg = e.getMessage();
        Assert.assertTrue(msg.matches("For security concern, account ADMIN has been locked. Please try again in \\d+ seconds. " + "Login failure again will be locked for 1 minutes.."));
    }
}

