public void testCreateTableIndexWithId() throws Exception {
    val modelId = "89af4ee2-2cdb-4b07-b39e-4c29856309aa";
    val clean = prepare(modelId);
    val indexPlanManager = NIndexPlanManager.getInstance(KylinConfig.getInstanceFromEnv(), "default");
    val origin = indexPlanManager.getIndexPlan(modelId);
    val originLayoutSize = origin.getAllLayouts().size();
    var response = indexPlanService.createTableIndex("default", CreateTableIndexRequest.builder().project("default").modelId("89af4ee2-2cdb-4b07-b39e-4c29856309aa").colOrder(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID", "TEST_KYLIN_FACT.CAL_DT", "TEST_KYLIN_FACT.LSTG_FORMAT_NAME", "TEST_KYLIN_FACT.LSTG_SITE_ID")).shardByColumns(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID")).isLoadData(true).layoutOverrideIndexes(new HashMap<String, String>() {

        {
            put("TEST_KYLIN_FACT.LSTG_FORMAT_NAME", "eq");
        }
    }).sortByColumns(Arrays.asList("TEST_KYLIN_FACT.CAL_DT")).build(), 20000040000L);
    Assert.assertEquals(BuildIndexResponse.BuildIndexType.NORM_BUILD, response.getType());
    val saved = indexPlanManager.getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    Assert.assertEquals(originLayoutSize + 1, saved.getAllLayouts().size());
    LayoutEntity newLayout = null;
