        if (newLayout == null) {
            newLayout = layout;
        } else {
            if (newLayout.getId() < layout.getId()) {
                newLayout = layout;
            }
        }
    }
    Assert.assertThat(newLayout.getColOrder(), CoreMatchers.is(Arrays.asList(1, 2, 3, 4)));
    Assert.assertThat(newLayout.getShardByColumns(), CoreMatchers.is(Arrays.asList(1)));
    Assert.assertThat(newLayout.getSortByColumns(), CoreMatchers.is(Arrays.asList()));
    indexPlanService.updateTableIndex("default", CreateTableIndexRequest.builder().id(20000040000L).project("default").modelId("89af4ee2-2cdb-4b07-b39e-4c29856309aa").colOrder(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID", "TEST_KYLIN_FACT.CAL_DT", "TEST_KYLIN_FACT.LSTG_FORMAT_NAME", "TEST_KYLIN_FACT.LSTG_SITE_ID")).shardByColumns(Arrays.asList("TEST_KYLIN_FACT.CAL_DT")).sortByColumns(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID")).build());
    Assert.assertFalse(indexPlanService.getManager(NIndexPlanManager.class, "default").getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa").getAllLayouts().stream().anyMatch(l -> l.getId() == 20000040000L));
    Assert.assertTrue(indexPlanService.getManager(NIndexPlanManager.class, "default").getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa").getAllLayouts().stream().anyMatch(l -> l.getId() == 20000040000L + IndexEntity.INDEX_ID_STEP));
}

