@Test
public void testRepairBrokenModelAfterReloadMoreThanOneTable() throws IOException {
    String modelId = "722b027b-8906-379b-cf4f-ac2055ee528b";
    NDataModelManager dataModelManager = NDataModelManager.getInstance(getTestConfig(), PROJECT_NAME);
    ModelRequest modelRequest = JsonUtil.readValue(new File("src/test/resources/ut_meta/broken_repair_test/model_request/model_request_broken_aftr_reload.json"), ModelRequest.class);
    modelRequest.setProject(PROJECT_NAME);
    modelService.detectInvalidIndexes(modelRequest);
    NDataModel brokenDataModelDesc = dataModelManager.getDataModelDescWithoutInit(modelId);
    Assert.assertEquals(1, brokenDataModelDesc.getComputedColumnDescs().size());
    Assert.assertEquals(29, brokenDataModelDesc.getAllNamedColumns().stream().filter(NDataModel.NamedColumn::isExist).count());
    Assert.assertEquals(8, brokenDataModelDesc.getAllMeasures().stream().filter(NDataModel.Measure::isTomb).count());
    Assert.assertEquals(NDataModel.class, UnitOfWork.doInTransactionWithRetry(() -> modelService.repairBrokenModel(PROJECT_NAME, modelRequest), PROJECT_NAME).getClass());
}

