    // old indexes
    val indexCol = Arrays.asList(transId, nest5SumId);
    val oldLayoutId = indexPlanManager.getIndexPlan(modelId).getAllLayouts().stream().filter(l -> l.getColOrder().containsAll(indexCol)).findFirst().map(LayoutEntity::getId).orElse(-1L);
    // modify expression of cc TEST_KYLIN_FACT.NEST5
    val originCC = request.getComputedColumnDescs().stream().filter(c -> ("NEST5").equals(c.getColumnName())).findFirst().orElse(null);
