    });
    dimensions.add("TEST_KYLIN_FACT.DEAL_AMOUNT");
    dimensions.add("TEST_KYLIN_FACT.TRANS_ID");
    Assert.assertFalse(tdsService.checkColumnPermission(dataModel, newAuthColumns, dimensions, measurs));
