@Test
public void testQueryPushDownForced() throws Throwable {
    final String sql = "select * from abc";
    final String project = "default";
    final QueryExec queryExec = Mockito.mock(QueryExec.class);
    SQLRequest sqlRequest = new SQLRequest();
    sqlRequest.setSql(sql);
    sqlRequest.setProject(project);
    sqlRequest.setForcedToPushDown(true);
    QueryParams queryParams = new QueryParams(KapQueryUtil.getKylinConfig(sqlRequest.getProject()), sqlRequest.getSql(), sqlRequest.getProject(), sqlRequest.getLimit(), sqlRequest.getOffset(), queryExec.getDefaultSchemaName(), true);
    String correctedSql = KapQueryUtil.massageSql(queryParams);
    Mockito.when(queryExec.executeQuery(correctedSql)).thenThrow(new RuntimeException("shouldn't execute executeQuery"));
    Mockito.doThrow(new RuntimeException("shouldn't execute searchCache")).when(queryService).searchCache(Mockito.any(), Mockito.any());
    Mockito.doAnswer(x -> queryExec).when(queryService).newQueryExec(project);
    Mockito.when(queryService.newQueryExec(project)).thenReturn(queryExec);
    Mockito.doAnswer(x -> queryExec).when(queryService).newQueryExec(project, null);
    Mockito.when(queryService.newQueryExec(project, null)).thenReturn(queryExec);
    Mockito.doAnswer(invocation -> PushdownResult.emptyResult()).when(queryService.queryRoutingEngine).tryPushDownSelectQuery(Mockito.any(), Mockito.any(), Mockito.anyBoolean());
    final SQLResponse response = queryService.queryWithCache(sqlRequest);
    Assert.assertFalse(response.isStorageCacheUsed());
    Assert.assertTrue(response.isQueryPushDown());
}

